use crate::link_network::{integer, ipv4};
use crate::Packet;

pub fn type_name(kind: i64) -> String {
    match kind {
        1 => "A".into(), 2 => "NS".into(), 5 => "CNAME".into(), 6 => "SOA".into(),
        12 => "PTR".into(), 15 => "MX".into(), 16 => "TXT".into(), 28 => "AAAA".into(),
        _ => format!("TYPE{kind}"),
    }
}

pub fn rcode_name(code: i64) -> String {
    match code {
        0 => "NoError".into(), 1 => "FormErr".into(), 2 => "ServFail".into(),
        3 => "NXDomain".into(), 4 => "NotImp".into(), 5 => "Refused".into(),
        _ => format!("RCODE{code}"),
    }
}

struct Reader<'a> {
    bytes: &'a [u8],
}

impl Reader<'_> {
    fn need(&self, start: usize, length: usize) -> Result<(), String> {
        if start + length > self.bytes.len() { Err("dns: truncated".into()) } else { Ok(()) }
    }

    fn number(&self, start: usize, length: usize) -> Result<i64, String> {
        self.need(start, length)?;
        Ok(integer(self.bytes, start, length))
    }

    fn name(&self, mut position: usize) -> Result<(String, usize), String> {
        let mut labels = Vec::new();
        let mut after = None;
        let mut pointers = 0;
        loop {
            let c = self.number(position, 1)? as usize;
            if c == 0 {
                let end = after.unwrap_or(position + 1);
                return Ok((if labels.is_empty() { "<root>".into() } else { labels.join(".") }, end));
            }
            if c >= 192 {
                let d = self.number(position + 1, 1)? as usize;
                after.get_or_insert(position + 2);
                pointers += 1;
                if pointers > 16 {
                    return Err("dns: compression loop".into());
                }
                position = (c - 192) * 256 + d;
                if position >= self.bytes.len() {
                    return Err("dns: pointer out of range".into());
                }
            } else if c >= 64 {
                return Err("dns: bad label type".into());
            } else {
                self.need(position + 1, c)?;
                let label: String = self.bytes[position + 1..position + c + 1].iter().map(|&b| {
                    if (33..=126).contains(&b) && b != b'.' && b != b'\\' { (b as char).to_string() } else { format!("\\{b:03}") }
                }).collect();
                labels.push(label);
                position += c + 1;
            }
        }
    }

    fn rdata(&self, kind: i64, start: usize, length: usize) -> Result<(String, usize), String> {
        match kind {
            1 => Ok((ipv4(self.number(start, 4)?), start + 4)),
            28 => {
                self.need(start, 16)?;
                let groups: Vec<_> = (0..8).map(|i| integer(self.bytes, start + i * 2, 2)).collect();
                let mut best = (0, 0);
                let mut i = 0;
                while i < 8 {
                    if groups[i] != 0 {
                        i += 1;
                        continue;
                    }
                    let begin = i;
                    while i < 8 && groups[i] == 0 { i += 1; }
                    if i - begin >= 2 && i - begin > best.1 { best = (begin, i - begin); }
                }
                let join = |slice: &[i64]| slice.iter().map(|v| format!("{v:x}")).collect::<Vec<_>>().join(":");
                let text = if best.1 == 0 { join(&groups) } else { format!("{}::{}", join(&groups[..best.0]), join(&groups[best.0 + best.1..])) };
                Ok((text, start + 16))
            }
            2 | 5 | 12 => self.name(start),
            15 => {
                let preference = self.number(start, 2)?;
                let (name, end) = self.name(start + 2)?;
                Ok((format!("{preference} {name}"), end))
            }
            6 => {
                let (m, after_m) = self.name(start)?;
                let (n, after_n) = self.name(after_m)?;
                let mut text = format!("{m} {n}");
                for i in 0..5 {
                    text.push_str(&format!(" {}", self.number(after_n + i * 4, 4)?));
                }
                Ok((text, after_n + 20))
            }
            _ => Ok((format!("{length} bytes"), start + length)),
        }
    }
}

pub fn dissect(packet: &mut Packet, bytes: &[u8]) -> Result<Vec<u8>, String> {
    let reader = Reader { bytes };
    reader.need(0, 12)?;
    let mut staged = Packet::new(0, 0, 0);
    let flags = reader.number(2, 2)?;
    for (field, value) in [
        ("dns.id", reader.number(0, 2)?), ("dns.flags", flags), ("dns.flags.response", (flags >> 15) & 1),
        ("dns.flags.opcode", (flags / 2048) % 16), ("dns.flags.rcode", flags % 16),
        ("dns.count.queries", reader.number(4, 2)?), ("dns.count.answers", reader.number(6, 2)?),
        ("dns.count.auth_rr", reader.number(8, 2)?), ("dns.count.add_rr", reader.number(10, 2)?),
    ] {
        staged.set_num(field, value);
    }
    let mut position = 12;
    for _ in 0..staged.num("dns.count.queries") {
        let (name, after) = reader.name(position)?;
        reader.need(after, 4)?;
        staged.append_text("dns.qry.name", name);
        staged.append_num("dns.qry.type", reader.number(after, 2)?);
        position = after + 4;
    }
    for (count, field) in [("dns.count.answers", "dns.answer"), ("dns.count.auth_rr", "dns.authority"), ("dns.count.add_rr", "dns.additional")] {
        for _ in 0..staged.num(count) {
            let (name, after) = reader.name(position)?;
            reader.need(after, 10)?;
            let kind = reader.number(after, 2)?;
            let class = reader.number(after + 2, 2)?;
            let ttl = reader.number(after + 4, 4)?;
            let length = reader.number(after + 8, 2)? as usize;
            let start = after + 10;
            reader.need(start, length)?;
            let (data, end) = reader.rdata(kind, start, length)?;
            if end != start + length { return Err("dns: bad rdata length".into()); }
            let class_name = if class == 1 { "IN".into() } else { format!("CLASS{class}") };
            staged.append_text(field, format!("{} {} {} {} {}", name, type_name(kind), class_name, ttl, data));
            if field == "dns.answer" {
                staged.answers.push((kind, data));
                if kind == 1 { staged.append_num("dns.a", reader.number(start, 4)?); }
            }
            position = start + length;
        }
    }
    packet.fields.extend(staged.fields);
    packet.answers = staged.answers;
    Ok(Vec::new())
}

use crate::link_network::ipv4;
use crate::{seconds, Packet};
use std::collections::{BTreeMap, BTreeSet};

type Endpoint = (i64, i64);
pub const MARKS: [&str; 4] = ["retransmission", "out_of_order", "lost_segment", "duplicate_ack"];

#[derive(Default)]
struct Side {
    isn: Option<i64>,
    mss: Option<i64>,
    ws: Option<i64>,
    base: Option<i64>,
    expected: Option<i64>,
    advanced: i64,
    intervals: BTreeSet<(i64, i64)>,
    previous_ack: Option<(i64, i64, i64, i64)>,
    packets: i64,
    payload: i64,
    marks: [i64; 4],
}

pub struct Stream {
    client: Endpoint,
    server: Endpoint,
    state: &'static str,
    history: Vec<(&'static str, i64)>,
    start: i64,
    end: i64,
    packets: i64,
    bytes: i64,
    handshake: [Option<i64>; 3],
    events: Vec<(i64, usize, usize, i64, i64)>,
    closed_first: Option<usize>,
    f2: i64,
    sides: [Side; 2],
}

fn record_syn(stream: &mut Stream, side: usize, packet: &Packet) {
    stream.sides[side].isn = Some(packet.num("tcp.seq_raw"));
    stream.sides[side].mss = packet.optional_num("tcp.options.mss");
    stream.sides[side].ws = packet.optional_num("tcp.options.wscale");
    stream.handshake[side] = Some(packet.number);
}

pub fn track(packets: &mut [Packet]) -> Vec<Stream> {
    let mut streams: Vec<Stream> = Vec::new();
    for packet in packets.iter_mut().filter(|p| p.has("tcp.srcport")) {
        let source = (packet.num("ip.src"), packet.num("tcp.srcport"));
        let destination = (packet.num("ip.dst"), packet.num("tcp.dstport"));
        let flags = packet.num("tcp.flags");
        let syn = flags & 2 != 0;
        let ack_set = flags & 16 != 0;
        let fin = flags & 1 != 0;
        let rst = flags & 4 != 0;
        let seq = packet.num("tcp.seq_raw");
        let ack = packet.num("tcp.ack_raw");
        let existing = streams.iter().rposition(|s| (s.client == source && s.server == destination) || (s.client == destination && s.server == source));
        let create = existing.is_none_or(|i| ["CLOSED", "RESET"].contains(&streams[i].state) && syn && !ack_set);
        let index = if create {
            let reverse = syn && ack_set;
            let state = if reverse { "SYN_RECEIVED" } else if syn { "SYN_SENT" } else { "ESTABLISHED" };
            let mut stream = Stream {
                client: if reverse { destination } else { source },
                server: if reverse { source } else { destination },
                state, history: vec![(state, packet.number)], start: packet.time, end: packet.time,
                packets: 0, bytes: 0, handshake: [None; 3], events: Vec::new(),
                closed_first: None, f2: 0, sides: [Side::default(), Side::default()],
            };
            if syn { record_syn(&mut stream, usize::from(reverse), packet); }
            streams.push(stream);
            streams.len() - 1
        } else { existing.unwrap() };
        packet.set_num("tcp.stream", index as i64);
        let stream = &mut streams[index];
        let side_index = usize::from(source != stream.client);
        let other = 1 - side_index;
        let base = *stream.sides[side_index].base.get_or_insert(seq);
        let relative = (seq - base).rem_euclid(1_i64 << 32);
        packet.set_num("tcp.seq", relative);
        if ack_set {
            let other_base = *stream.sides[other].base.get_or_insert(ack);
            packet.set_num("tcp.ack", (ack - other_base).rem_euclid(1_i64 << 32));
        }
        let length = packet.num("tcp.len") + i64::from(syn) + i64::from(fin);
        let side = &mut stream.sides[side_index];
        let mut mark = None;
        if length > 0 {
            if let Some(expected) = side.expected {
                if relative > expected {
                    mark = Some(2);
                } else if relative < expected {
                    mark = Some(if side.intervals.contains(&(relative, length)) || packet.time - side.advanced >= 3000 { 0 } else { 1 });
                }
            }
            side.intervals.insert((relative, length));
            if side.expected.is_none_or(|e| relative + length > e) {
                side.expected = Some(relative + length);
                side.advanced = packet.time;
            }
        } else if ack_set && !rst {
            if let Some(previous) = side.previous_ack.as_mut() {
                if previous.0 == ack && previous.1 == packet.num("tcp.window") {
                    mark = Some(3);
                    previous.3 += 1;
                    packet.duplicate = Some((previous.2, previous.3));
                }
            }
        }
        if ack_set && mark != Some(3) {
            side.previous_ack = Some((ack, packet.num("tcp.window"), packet.number, 0));
        }
        if let Some(mark) = mark {
            side.marks[mark] += 1;
            packet.present(&format!("tcp.analysis.{}", MARKS[mark]));
            stream.events.push((packet.number, side_index, mark, relative, length));
        }
        let window = packet.num("tcp.window");
        let calculated = if !syn && stream.sides.iter().all(|s| s.ws.is_some()) {
            window * (1_i64 << stream.sides[side_index].ws.unwrap())
        } else { window };
        packet.set_num("tcp.window.calc", calculated);
        let old_state = stream.state;
        if rst {
            if !["CLOSED", "RESET"].contains(&stream.state) { stream.state = "RESET"; }
        } else if stream.state == "SYN_SENT" && side_index == 1 && syn && ack_set && stream.sides[0].isn.is_some_and(|isn| ack == (isn + 1) % (1_i64 << 32)) {
            stream.state = "SYN_RECEIVED";
            record_syn(stream, 1, packet);
        } else if stream.state == "SYN_RECEIVED" && side_index == 0 && ack_set && !syn && stream.sides[1].isn.is_some_and(|isn| ack == (isn + 1) % (1_i64 << 32)) {
            stream.state = "ESTABLISHED";
            stream.handshake[2] = Some(packet.number);
        } else if stream.state == "ESTABLISHED" && fin {
            stream.state = "FIN_WAIT";
            stream.closed_first = Some(side_index);
        } else if stream.state == "FIN_WAIT" && fin && stream.closed_first != Some(side_index) {
            stream.state = "CLOSING";
            stream.f2 = (seq + packet.num("tcp.len") + 1) % (1_i64 << 32);
        } else if stream.state == "CLOSING" && stream.closed_first == Some(side_index) && ack_set && ack == stream.f2 {
            stream.state = "CLOSED";
        }
        if stream.state != old_state { stream.history.push((stream.state, packet.number)); }
        stream.sides[side_index].packets += 1;
        stream.sides[side_index].payload += packet.num("tcp.len");
        stream.packets += 1;
        stream.bytes += packet.length;
        stream.end = packet.time;
    }
    streams
}

fn endpoint_text(endpoint: Endpoint) -> String {
    if endpoint.1 < 0 { ipv4(endpoint.0) } else { format!("{}:{}", ipv4(endpoint.0), endpoint.1) }
}

fn optional(value: Option<i64>) -> String {
    value.map_or_else(|| "-".into(), |v| v.to_string())
}

pub fn stream_lines(streams: &[Stream], packets: &[Packet]) -> Vec<String> {
    let mut lines = Vec::new();
    for (index, stream) in streams.iter().enumerate() {
        if index != 0 { lines.push(String::new()); }
        lines.push(format!("stream {index} {} -> {}", endpoint_text(stream.client), endpoint_text(stream.server)));
        lines.push(format!("packets {} bytes {} start {} duration {}", stream.packets, stream.bytes, seconds(stream.start - packets[0].time), seconds(stream.end - stream.start)));
        lines.push(format!("states {}", stream.history.iter().map(|(state, n)| format!("{state} {n}")).collect::<Vec<_>>().join(", ")));
        let rtt = match (stream.handshake[0], stream.handshake[2]) {
            (Some(syn), Some(ack)) => seconds(packets[ack as usize - 1].time - packets[syn as usize - 1].time),
            _ => "-".into(),
        };
        lines.push(format!("handshake syn {} syn_ack {} ack {} rtt {}", optional(stream.handshake[0]), optional(stream.handshake[1]), optional(stream.handshake[2]), rtt));
        lines.push(format!("options client mss {} wscale {} server mss {} wscale {}", optional(stream.sides[0].mss), optional(stream.sides[0].ws), optional(stream.sides[1].mss), optional(stream.sides[1].ws)));
        for (name, side) in ["client", "server"].iter().zip(&stream.sides) {
            lines.push(format!("{} packets {} payload {} retransmission {} out_of_order {} lost_segment {} duplicate_ack {}", name, side.packets, side.payload, side.marks[0], side.marks[1], side.marks[2], side.marks[3]));
        }
        for &(n, side, mark, relative, length) in &stream.events {
            lines.push(format!("event {} {} {} seq {} len {}", n, ["client", "server"][side], MARKS[mark], relative, length));
        }
    }
    lines
}

struct Conversation {
    kind: usize,
    a: Endpoint,
    b: Endpoint,
    counts: [i64; 4],
    start: i64,
    end: i64,
    first: i64,
}

pub fn tables(packets: &[Packet]) -> (Vec<String>, Vec<String>) {
    let mut conversations: BTreeMap<(usize, i64, Endpoint, Endpoint), Conversation> = BTreeMap::new();
    let mut endpoints: BTreeMap<i64, [i64; 4]> = BTreeMap::new();
    for packet in packets.iter().filter(|p| p.has("ip.src")) {
        let source = packet.num("ip.src");
        let destination = packet.num("ip.dst");
        let tx = endpoints.entry(source).or_default();
        tx[0] += 1;
        tx[1] += packet.length;
        let rx = endpoints.entry(destination).or_default();
        rx[2] += 1;
        rx[3] += packet.length;
        let mut kinds = vec![(0, -1, (source, -1), (destination, -1))];
        if packet.has("tcp.stream") { kinds.push((1, packet.num("tcp.stream"), (source, packet.num("tcp.srcport")), (destination, packet.num("tcp.dstport")))); }
        if packet.has("udp.srcport") { kinds.push((2, -1, (source, packet.num("udp.srcport")), (destination, packet.num("udp.dstport")))); }
        for (kind, stream, a, b) in kinds {
            let key = (kind, stream, a.min(b), a.max(b));
            let conversation = conversations.entry(key).or_insert(Conversation {
                kind, a, b, counts: [0; 4], start: packet.time, end: packet.time, first: packet.number,
            });
            let direction = if a == conversation.a { 0 } else { 2 };
            conversation.counts[direction] += 1;
            conversation.counts[direction + 1] += packet.length;
            conversation.end = packet.time;
        }
    }
    let mut conversations: Vec<_> = conversations.into_values().collect();
    conversations.sort_by_key(|c| (-(c.counts[1] + c.counts[3]), -(c.counts[0] + c.counts[2]), c.kind, c.first));
    let mut conversation_lines = vec!["type,endpoint_a,endpoint_b,packets,bytes,packets_a_to_b,bytes_a_to_b,packets_b_to_a,bytes_b_to_a,start,duration".into()];
    for c in conversations {
        conversation_lines.push(format!("{},{},{},{},{},{},{},{},{},{},{}", ["ipv4", "tcp", "udp"][c.kind], endpoint_text(c.a), endpoint_text(c.b), c.counts[0] + c.counts[2], c.counts[1] + c.counts[3], c.counts[0], c.counts[1], c.counts[2], c.counts[3], seconds(c.start - packets[0].time), seconds(c.end - c.start)));
    }
    let mut endpoints: Vec<_> = endpoints.into_iter().collect();
    endpoints.sort_by_key(|&(address, c)| (-(c[1] + c[3]), -(c[0] + c[2]), address));
    let mut endpoint_lines = vec!["address,packets,bytes,tx_packets,tx_bytes,rx_packets,rx_bytes".into()];
    for (address, c) in endpoints {
        endpoint_lines.push(format!("{},{},{},{},{},{},{}", ipv4(address), c[0] + c[2], c[1] + c[3], c[0], c[1], c[2], c[3]));
    }
    (conversation_lines, endpoint_lines)
}

use crate::Packet;
use std::fs;

pub fn read_capture(path: &str) -> Vec<Packet> {
    let input = fs::read_to_string(path).unwrap();
    let mut packets: Vec<Packet> = Vec::new();
    for (line_index, line) in input.lines().enumerate() {
        if line.starts_with("PACKET ") {
            if let Some(packet) = packets.last_mut() {
                finish(packet);
            }
            let parts: Vec<_> = line.split(' ').collect();
            packets.push(Packet::new(parts[1].parse().unwrap(), parts[2].parse().unwrap(), parts[3].parse().unwrap()));
        } else if !line.is_empty() {
            let packet = packets.last_mut().unwrap();
            if packet.reason.is_some() {
                continue;
            }
            let bytes = line.as_bytes();
            let hex = |b: u8| b.is_ascii_digit() || (b'a'..=b'f').contains(&b);
            let valid_prefix = bytes.len() >= 8 && bytes[..4].iter().all(|&b| hex(b)) && &bytes[4..6] == b"  ";
            let parts: Vec<_> = if valid_prefix { line[6..].split(' ').collect() } else { Vec::new() };
            if !valid_prefix || parts.is_empty() || parts.len() > 16 || parts.iter().any(|p| p.len() != 2 || !p.bytes().all(hex)) {
                packet.reason = Some(format!("dump: bad line {}", line_index + 1));
            } else if usize::from_str_radix(&line[..4], 16).unwrap() != packet.bytes.len() {
                packet.reason = Some(format!("dump: offset mismatch at line {}", line_index + 1));
            } else {
                packet.bytes.extend(parts.iter().map(|p| u8::from_str_radix(p, 16).unwrap()));
            }
        }
    }
    finish(packets.last_mut().unwrap());
    packets
}

fn finish(packet: &mut Packet) {
    if packet.reason.is_none() && packet.bytes.len() as i64 != packet.length {
        packet.reason = Some(format!("dump: length mismatch (header {}, data {})", packet.length, packet.bytes.len()));
    }
}

pub fn dump(data: &[u8]) -> Vec<String> {
    data.chunks(16).enumerate().map(|(i, row)| {
        let hex = row.iter().map(|b| format!("{b:02x}")).collect::<Vec<_>>().join(" ");
        let ascii: String = row.iter().map(|&b| if (32..=126).contains(&b) { b as char } else { '.' }).collect();
        format!("{:04x}  {:47}  |{}|", i * 16, hex, ascii)
    }).collect()
}

use crate::Packet;

pub fn integer(bytes: &[u8], start: usize, length: usize) -> i64 {
    bytes[start..start + length].iter().fold(0, |value, &b| value * 256 + i64::from(b))
}

pub fn checksum(bytes: &[u8]) -> &'static str {
    let mut sum: i64 = bytes.chunks(2).map(|p| i64::from(p[0]) * 256 + i64::from(*p.get(1).unwrap_or(&0))).sum();
    while sum > 65535 {
        sum = sum % 65536 + sum / 65536;
    }
    if sum == 65535 { "good" } else { "bad" }
}

pub fn ipv4(value: i64) -> String {
    (0..4).rev().map(|i| ((value >> (i * 8)) & 255).to_string()).collect::<Vec<_>>().join(".")
}

pub fn mac(value: i64) -> String {
    (0..6).rev().map(|i| format!("{:02x}", (value >> (i * 8)) & 255)).collect::<Vec<_>>().join(":")
}

pub fn ethernet(packet: &mut Packet, bytes: &[u8]) -> Result<Vec<u8>, String> {
    if bytes.len() < 14 {
        return Err("eth: truncated".into());
    }
    packet.set_num("eth.dst", integer(bytes, 0, 6));
    packet.set_num("eth.src", integer(bytes, 6, 6));
    packet.set_num("eth.type", integer(bytes, 12, 2));
    Ok(bytes[14..].to_vec())
}

pub fn arp(packet: &mut Packet, bytes: &[u8]) -> Result<Vec<u8>, String> {
    if bytes.len() < 28 {
        return Err("arp: truncated".into());
    }
    if integer(bytes, 0, 2) != 1 || integer(bytes, 2, 2) != 2048 || bytes[4] != 6 || bytes[5] != 4 {
        return Err("arp: unsupported format".into());
    }
    for (field, offset, length) in [("arp.opcode", 6, 2), ("arp.src.hw", 8, 6), ("arp.src.ip", 14, 4), ("arp.dst.hw", 18, 6), ("arp.dst.ip", 24, 4)] {
        packet.set_num(field, integer(bytes, offset, length));
    }
    Ok(Vec::new())
}

pub fn ipv4_layer(packet: &mut Packet, bytes: &[u8]) -> Result<Vec<u8>, String> {
    if bytes.len() < 20 {
        return Err("ip: truncated header".into());
    }
    let version = bytes[0] / 16;
    if version != 4 {
        return Err(format!("ip: bad version {version}"));
    }
    let header = usize::from(bytes[0] % 16) * 4;
    if header < 20 {
        return Err(format!("ip: bad header length {header}"));
    }
    if bytes.len() < header {
        return Err("ip: truncated header".into());
    }
    let total = integer(bytes, 2, 2) as usize;
    if total < header {
        return Err(format!("ip: bad total length {total}"));
    }
    if total > bytes.len() {
        return Err(format!("ip: truncated (total length {total}, available {})", bytes.len()));
    }
    let flags = integer(bytes, 6, 2);
    for (field, value) in [
        ("ip.hdr_len", header as i64), ("ip.tos", i64::from(bytes[1])), ("ip.len", total as i64),
        ("ip.id", integer(bytes, 4, 2)), ("ip.flags.df", (flags >> 14) & 1),
        ("ip.flags.mf", (flags >> 13) & 1), ("ip.frag_offset", (flags % 8192) * 8),
        ("ip.ttl", i64::from(bytes[8])), ("ip.proto", i64::from(bytes[9])),
        ("ip.checksum", integer(bytes, 10, 2)), ("ip.src", integer(bytes, 12, 4)), ("ip.dst", integer(bytes, 16, 4)),
    ] {
        packet.set_num(field, value);
    }
    packet.set_text("ip.checksum.status", checksum(&bytes[..header]));
    if packet.num("ip.flags.mf") == 1 || packet.num("ip.frag_offset") != 0 {
        packet.present("ip.fragment");
    }
    Ok(bytes[header..total].to_vec())
}

